import sys

sys.setrecursionlimit(300005)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    q = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        p = int(next(iterator))
        adj[p].append(i)

    sz = [0] * (n + 1)
    order = []
    stack = [1]

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            stack.append(v)

    for u in reversed(order):
        s = 1
        for v in adj[u]:
            s += sz[v]
        sz[u] = s

    centroid = [0] * (n + 1)

    for u in order:
        curr = u
        total = sz[u]

        while True:
            max_comp = 0
            heavy_child = -1

            for v in adj[curr]:
                if sz[v] > max_comp:
                    max_comp = sz[v]
                    heavy_child = v

            parent_part = total - sz[curr]
            if parent_part > max_comp:
                max_comp = parent_part

            if max_comp <= total // 2:
                centroid[u] = curr
                break

            if heavy_child != -1:
                curr = heavy_child
            else:
                break

    output = []
    for _ in range(q):
        v = int(next(iterator))
        output.append(str(centroid[v]))

    sys.stdout.write('\n'.join(output) + '\n')

if __name__ == '__main__':
    main()
